from pathlib import Path
import json,hashlib,re,sys
W=Path(__file__).resolve().parent
sys.path.insert(0,'/Volumes/LaCie/open-commentary/_tools');from build_repo import load_commentary
c=load_commentary(str(W))
(W/'sources/review-art-106a-120-before-hashes.json').write_text(json.dumps({k:hashlib.sha256(v.encode()).hexdigest() for k,v in c.items()},indent=2)+'\n')
add={
'art-106a':'''Onder d moet het gaan om ten minste twee eerdere betrokkenheden bij een faillissement van een rechtspersoon of een beëindiging volgens de in de wettekst genoemde verwijzing naar artikel 19c lid 1, aanhef. Ook het persoonlijke verwijt moet worden vastgesteld. De verwijzing betreft niet iedere vrijwillige ontbinding; de precieze wettelijke beëindigingsroute is onderdeel van de grond. Lid 4 zondert bij beroeps- of bedrijfsmatig handelende natuurlijke personen zowel grond a als de bestuurdersketen van lid 2 uit.

Een concreet voorbeeld van grond c biedt [Rb. Overijssel 8 april 2020, ECLI:NL:RBOVE:2020:1557](cases/RBOVE-2020-1557.md), rov. 4.3–4.5 en 5.1. De rechtbank achtte het niet afgeven van de volledige digitale en fysieke administratie ondanks verzoeken ernstig genoeg voor een vijfjarig verbod. Dat de curator zelf enkele stukken had achterhaald, nam die tekortkoming niet weg. De rechtbank liet de daarnaast aangevoerde herhalingsgrond uitdrukkelijk onbeslist. Het vonnis bewijst dus geen persoonlijk verwijt bij de twee eerdere faillissementen en beoordeelt evenmin de later toegevoegde beëindigingsvariant van grond d.''',
'art-106b':'''De uitzondering op uitvoerbaarheid bij voorraad betreft de oplegging van het bestuursverbod. Zij moet niet automatisch worden uitgebreid tot elke andere veroordeling in hetzelfde vonnis. In [Rb. Overijssel 8 april 2020, ECLI:NL:RBOVE:2020:1557](cases/RBOVE-2020-1557.md), dictum 5.1 en 5.4–5.5, liet de rechtbank het verbod ingaan na kracht van gewijsde en gaf zij opdracht tot aanbieding aan de Kamer van Koophandel na onherroepelijkheid; alleen de proces- en nakostenveroordelingen verklaarde zij uitvoerbaar bij voorraad. De concrete uitspraak illustreert daarmee het belang van afzonderlijke lezing van de onderdelen van het dictum.''',
'art-106c':'''De curator of het openbaar ministerie moet het uittreksel bij de vordering of het verzoek overleggen; de Kamer van Koophandel verstrekt het op hun verzoek. Bij de tijdelijke benoeming van lid 3 stelt de rechtbank de bezoldiging vast. Voor schorsing tijdens een lopend geding verlangt lid 4 opnieuw een verzoek van het openbaar ministerie of vordering van de curator. Lid 5 laat dit in elke stand van het geding toe, maar geeft geen voorlopige benoeming die zelfstandig na het einde van het geding doorloopt; registratie volgens lid 6 volgt de duur van de voorlopige maatregel.''',
'art-110':'''Het bijzondere lid 3 ziet op gerechtigden die niet de daar bedoelde mededeling van artikel 7:908 lid 2 BW hebben gedaan. De vervaltermijn is geen automatische wettelijke sanctie: de verbindend verklaarde overeenkomst kan haar opnemen. De minimumduur van drie maanden begint pas op de dag na het verstrijken van de in die verwijzing bedoelde termijn. Controleer daarom zowel de toepasselijkheid van de overeenkomst als haar eigen beding en het juiste aanvangsmoment. De laatste zin verklaart artikelen 128, 133 en 136 overeenkomstig van toepassing: ook binnen deze bijzondere route blijven respectievelijk de regeling van na faillissement lopende rente, de waardering in Nederlands geld en het tegengaan van dubbele voldoening bij hoofdelijke schulden relevant. Die verwijzingen geven geen vrijstelling van de overeengekomen indieningswijze.''',
'art-114':'''De wettelijke inzage is toegankelijk voor een ieder, dus ook voor wie geen schuldeiser is. Kosteloze inzage en kosteloze neerlegging zijn verschillende onderdelen van het artikel; zij maken een verzocht afschrift niet vanzelf kosteloos, waarvoor artikel 107 een eigen kostenregel geeft. Een belangstellende die de lijsten wil lezen hoeft zijn eigen schuldvordering daarom niet eerst te bewijzen, terwijl een verzoek om toezending van kopieën afzonderlijk moet worden behandeld.''',
'art-119':'''De in lid 2 bedoelde geloofsverklaring geldt nauwkeurig voor de rechthebbenden wanneer de oorspronkelijke schuldeiser is overleden; zij is geen algemene vervanging van de eed voor iedere verkrijger van een vordering. De verklaring ziet zowel op het bestaan als op het onvoldaan zijn van de schuld. Lid 1 kent de genoemde vraag- en betwistingsbevoegdheden toe aan schuldeisers die op de lijsten voorkomen. De curator kan de eed verlangen voor een vordering die noch door hemzelf noch door een schuldeiser is betwist. Een inhoudelijk betwiste factuur wordt dus niet louter door die eedsroute een onbetwiste vordering; artikel 122 regelt de verdere behandeling van een blijvend geschil.'''
}
for p in (W/'commentary').glob('*.md'):
 s=p.read_text();parts=re.split(r'(?m)(^=== \S+\n)',s)
 for i in range(1,len(parts),2):
  k=parts[i].strip()[4:]
  if k in add:parts[i+1]=parts[i+1].rstrip()+'\n\n'+add[k]+'\n\n'
 if ''.join(parts)!=s:p.write_text(''.join(parts))
